@layer tokens, components;

@layer tokens {
  :root {
    color-scheme: light;

    --text-heading: #111;
    --text-body: #444;
    --text-sub: #767676;
    --text-disabled: color-mix(in srgb, var(--text-heading) 38%, transparent);
    --link: var(--text-heading);

    --font-sans: system-ui, sans-serif;
    --font-mono: ui-monospace, monospace;

    --bg: #fff;
    --bg-hover: #f3f2f1;
    --bg-well: #e8e6e4;
    --bg-overlay: var(--bg);

    --ink: #111;
    --on-ink: #fff;
    --shine: #fff;
    --error: #8f3232;
    --on-error: #fff;
    --success: #2f6b3a;
    --on-success: #fff;
    --warning: #8a5a12;
    --on-warning: #fff;
    --info: #2c4a6e;
    --on-info: #fff;
    --line: color-mix(in srgb, var(--text-heading) 18%, transparent);
    --focus: color-mix(in srgb, var(--text-heading) 70%, transparent);

    --z-base: 0;
    --z-nav: 10;
    --z-overlay: 20;
    --z-toast: 30;

    --bp-md: 48rem;

    --ratio: 1.25;

    --type-md: 1rem;
    --type-sm: calc(var(--type-md) / var(--ratio));
    --type-xs: calc(var(--type-sm) / var(--ratio));
    --type-lg: calc(var(--type-md) * var(--ratio));
    --type-xl: calc(var(--type-lg) * var(--ratio));
    --type-2xl: calc(var(--type-xl) * var(--ratio));

    --control: calc(
      var(--type-md) * var(--leading-tight) + var(--space-4) * 2
    );

    --leading-tight: var(--ratio);
    --leading: calc(var(--ratio) * var(--ratio));

    --weight-regular: 400;
    --weight-medium: 500;

    --space: 0.25rem;
    --space-1: var(--space);
    --space-2: calc(var(--space-1) * var(--ratio));
    --space-3: calc(var(--space-2) * var(--ratio));
    --space-4: calc(var(--space-3) * var(--ratio));
    --space-5: calc(var(--space-4) * var(--ratio));
    --space-6: calc(var(--space-5) * var(--ratio));
    --space-7: calc(var(--space-6) * var(--ratio));
    --space-8: calc(var(--space-7) * var(--ratio));
    --space-9: calc(var(--space-8) * var(--ratio));
    --space-10: calc(var(--space-9) * var(--ratio));
    --space-11: calc(var(--space-10) * var(--ratio));
    --space-12: calc(var(--space-11) * var(--ratio));
    --space-13: calc(var(--space-12) * var(--ratio));
    --space-14: calc(var(--space-13) * var(--ratio));

    --radius: var(--space-3);

    --highlight: oklch(1 0 0 / 62%);
    --shade: oklch(0 0 0 / 28%);

    --tool:
      inset 0 1px 0 0 var(--highlight),
      inset 0 -1px 0 0 var(--shade),
      inset 1px 0 0 0 color-mix(in srgb, var(--highlight) 50%, transparent),
      inset -1px 0 0 0 color-mix(in srgb, var(--shade) 70%, transparent);
    --lift:
      0 1px 0 color-mix(in srgb, var(--shade) 90%, transparent),
      0 2px 0 color-mix(in srgb, var(--shade) 50%, transparent);
    --raise: var(--tool), var(--lift);
    --flat:
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      0 0 0 transparent,
      0 0 0 transparent;
    --well:
      inset 0 1px 0 var(--shade),
      inset 0 2px 0 color-mix(in srgb, var(--shade) 60%, transparent),
      inset 0 4px 6px color-mix(in srgb, var(--shade) 80%, transparent),
      inset 0 -1px 0 var(--highlight);
    --press:
      inset 0 1px 0 0 var(--shade),
      inset 0 -1px 0 0 var(--highlight),
      inset 1px 0 0 0 color-mix(in srgb, var(--shade) 70%, transparent),
      inset -1px 0 0 0 color-mix(in srgb, var(--highlight) 50%, transparent),
      0 0 0 transparent,
      0 0 0 transparent;
    --face: linear-gradient(
      180deg,
      color-mix(in srgb, var(--bg) 62%, var(--shine)) 0%,
      var(--bg) 42%,
      color-mix(in srgb, var(--bg) 78%, var(--bg-well)) 100%
    );
    --face-press: linear-gradient(
      180deg,
      color-mix(in srgb, var(--bg) 74%, var(--shine)) 0%,
      var(--bg) 50%,
      color-mix(in srgb, var(--bg) 72%, var(--bg-well)) 100%
    );

    --ns-key: var(--ink);
    --ns-on-key: var(--on-ink);
    --key-face: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 68%, var(--shine)) 0%,
      var(--ns-key) 52%,
      color-mix(in srgb, var(--ns-key) 82%, oklch(0 0 0)) 100%
    );
    --key-face-hover: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 56%, var(--shine)) 0%,
      var(--ns-key) 48%,
      color-mix(in srgb, var(--ns-key) 88%, oklch(0 0 0)) 100%
    );
    --key-face-press: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 74%, var(--shine)) 0%,
      var(--ns-key) 56%,
      color-mix(in srgb, var(--ns-key) 84%, oklch(0 0 0)) 100%
    );

    --ease: cubic-bezier(0.22, 1, 0.36, 1);
    --duration: 200ms;
  }

  @media (prefers-reduced-motion: reduce) {
    :root {
      --duration: 0ms;
    }
  }

  [data-density="compact"] {
    --control: calc(
      var(--type-sm) * var(--leading-tight) + var(--space-3) * 2
    );
  }

  @media (prefers-color-scheme: dark) {
    :root:not(.light) {
      color-scheme: dark;
      --text-heading: #f5f5f5;
      --text-body: #b3b3b3;
      --text-sub: #8a8a8a;
      --bg: #1a1a1a;
      --bg-hover: #242424;
      --bg-well: #111;
      --ink: #f5f5f5;
      --on-ink: #111;
      --shine: #303030;
      --error: #b33b3b;
      --on-error: #fff;
      --success: #4a9a58;
      --on-success: #111;
      --warning: #c4922a;
      --on-warning: #111;
      --info: #6a92c4;
      --on-info: #111;
      --highlight: oklch(1 0 0 / 36%);
      --shade: oklch(0 0 0 / 58%);
      --lift:
        0 1px 0 oklch(0 0 0 / 40%),
        0 2px 0 oklch(0 0 0 / 16%);
    }
  }

  :root.dark {
    color-scheme: dark;
    --text-heading: #f5f5f5;
    --text-body: #b3b3b3;
    --text-sub: #8a8a8a;
    --bg: #1a1a1a;
    --bg-hover: #242424;
    --bg-well: #111;
    --ink: #f5f5f5;
    --on-ink: #111;
    --shine: #303030;
    --error: #b33b3b;
    --on-error: #fff;
    --success: #4a9a58;
    --on-success: #111;
    --warning: #c4922a;
    --on-warning: #111;
    --info: #6a92c4;
    --on-info: #111;
    --highlight: oklch(1 0 0 / 36%);
    --shade: oklch(0 0 0 / 58%);
    --lift:
      0 1px 0 oklch(0 0 0 / 40%),
      0 2px 0 oklch(0 0 0 / 16%);
  }

  :root.light {
    color-scheme: light;
    --text-heading: #111;
    --text-body: #444;
    --text-sub: #767676;
    --bg: #fff;
    --bg-hover: #f3f2f1;
    --bg-well: #e8e6e4;
    --ink: #111;
    --on-ink: #fff;
    --shine: #fff;
    --error: #8f3232;
    --on-error: #fff;
    --success: #2f6b3a;
    --on-success: #fff;
    --warning: #8a5a12;
    --on-warning: #fff;
    --info: #2c4a6e;
    --on-info: #fff;
    --highlight: oklch(1 0 0 / 62%);
    --shade: oklch(0 0 0 / 28%);
  }
}

@layer components {
  .ns-sr {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
}

:focus:not(:focus-visible) {
  outline: none;
}

:focus-visible {
  outline: 5px auto Highlight;
  outline: 5px auto -webkit-focus-ring-color;
  outline-offset: 0;
}
